head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > M > setPanelTitle]<br/>파라미터로 지정한 ID 에 해당하는 패널의 타이틀 텍스트를 설정합니다.",
    "validation" : [
        "파라미터로 지정한 ID 에 해당하는 패널의 타이틀 텍스트를 설정합니다.",
        "id(필수) 타이틀을 설정할 패널의 디자인 ID 를 설정합니다.",
        "title(필수) 패널의 타이틀에 표시할 새로운 값을 문자열로 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // setPanelTitle 은 con_ 옵션 없음 (par_id, par_title 만 사용)
    let properties = {
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* setPanelTitle(id, title) 호출 → par_id 에 지정한 디자인 ID 의 패널 타이틀이 par_title 값으로 변경되는지 확인"', '', 'label1');
    $c.gcm.createLabel('label="* 초기 panelTitle 값 : panels1 → panelTitle1, panels2 → panelTitle2, panels3 → panelTitle3 (disabled)"', '', 'label2');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabled)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// setPanelTitle(par_id, par_title) 호출 — par_id 에 지정한 디자인 ID 의 패널 타이틀을 par_title 값으로 설정
scwin.btn_setPanelTitle_onclick = function (e) {
    let panelId = par_id.getValue();
    let title = par_title.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("===== setPanelTitle('" + panelId + "', '" + title + "') 호출 =====");
    target1.setPanelTitle(panelId, title);

    // 실제 적용된 panelTitle DOM 확인 (엔진: panel.render.childNodes[0].childNodes[1].innerHTML = title)
    let titleWrap = document.querySelector("[id$='_panel_" + panelId + "_title']");
    if (titleWrap && titleWrap.childNodes[1]) {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + panelId + " panelTitle 텍스트] " + titleWrap.childNodes[1].innerHTML);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + panelId + " panelTitle 텍스트] (DOM 없음)");
    }
};
